function minimumCost(nums) {
  let best = Infinity;
  for (let i = 1; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++) {
      const pieces = [nums.slice(0, i), nums.slice(i, j), nums.slice(j)];
      const total = pieces.reduce((sum, piece) => sum + piece[0], 0);
      if (total < best) best = total;
    }
  return best;
}

